<?php
require_once "includes/header.php";
$codigo=trim($_POST['codigo']??$_GET['codigo']??''); $pedido=null; $mensagens=[];
if($codigo){$stmt=$pdo->prepare("SELECT * FROM dpo_pedidos WHERE codigo=?");$stmt->execute([$codigo]);$pedido=$stmt->fetch(PDO::FETCH_ASSOC); if($pedido){$stmt=$pdo->prepare("SELECT * FROM dpo_mensagens WHERE pedido_id=? ORDER BY criado_em ASC");$stmt->execute([$pedido['id']]);$mensagens=$stmt->fetchAll(PDO::FETCH_ASSOC);}}
function estadoDpo($e){return ['recebido'=>'Recebido','em_analise'=>'Em análise','respondido'=>'Respondido','arquivado'=>'Arquivado'][$e]??$e;}
?>
<style>.cons-dpo{background:linear-gradient(180deg,#f8fafc,#fff);padding:80px 0}.cons-card{max-width:900px;margin:auto;background:white;border:1px solid #e5e7eb;border-radius:30px;padding:30px;box-shadow:0 20px 55px rgba(0,0,0,.10)}.cons-card h1{color:#11151B;font-size:38px}.cons-form{display:flex;gap:10px;flex-wrap:wrap}.cons-form input{flex:1;min-width:260px;border:1px solid #dbe4ee;background:#f8fafc;border-radius:16px;padding:0 15px;min-height:54px;font-weight:800}.cons-btn{border:0;background:#242A30;color:white;border-radius:16px;padding:14px 18px;font-weight:900;cursor:pointer}.cons-status{background:#eef2ff;color:#242A30;border-radius:18px;padding:18px;margin-top:22px;font-weight:900}.cons-msg{background:#f8fafc;border:1px solid #e5e7eb;border-radius:18px;padding:16px;margin-top:12px}.cons-empty{background:#fee2e2;color:#991b1b;border-radius:18px;padding:16px;margin-top:20px;font-weight:900}</style>
<main class="cons-dpo"><div class="container"><div class="cons-card"><h1>Consultar Pedido RGPD</h1><p>Introduza o código recebido após submissão do pedido.</p><form method="POST" class="cons-form"><input type="text" name="codigo" placeholder="Ex: DPO-2026-ABCDEFGH" value="<?= htmlspecialchars($codigo) ?>" required><button class="cons-btn">Consultar</button></form><?php if($codigo&&!$pedido): ?><div class="cons-empty">Não foi encontrado nenhum pedido com esse código.</div><?php endif; ?><?php if($pedido): ?><div class="cons-status">Estado atual: <?= htmlspecialchars(estadoDpo($pedido['estado'])) ?></div><h2><?= htmlspecialchars($pedido['nome']) ?></h2><p><strong>Email:</strong> <?= htmlspecialchars($pedido['email']) ?></p><p><strong>Submetido em:</strong> <?= date('d/m/Y H:i', strtotime($pedido['criado_em'])) ?></p><h3>Mensagens</h3><?php foreach($mensagens as $m): ?><div class="cons-msg"><strong><?= $m['origem']==='dpo'?'Encarregado de Proteção de Dados':'Cidadão' ?></strong><br><?= nl2br(htmlspecialchars($m['mensagem'])) ?><br><small><?= date('d/m/Y H:i', strtotime($m['criado_em'])) ?></small></div><?php endforeach; ?><?php if(empty($mensagens)): ?><p>Ainda não existem mensagens associadas.</p><?php endif; ?><?php endif; ?></div></div></main><?php require_once "includes/footer.php"; ?>